/**
 * @brief Get system random data
 *
 * @param[in] range: random value in [0, range); zero selects the legacy 8-bit range
 *
 * @return random value
 */
int tkl_system_get_random(uint32_t range)
{
    // --- BEGIN: user implements ---
    const uint32_t bound = range == 0U ? UINT32_C(256) : range;
    uint32_t sample;
    int status;

    if (bound == 1U) {
        return 0;
    }
    const uint32_t threshold = (uint32_t)(0U - bound) % bound;
    do {
        status = gd32h77x_random_sample(&sample);
        if (status != OPRT_OK) {
            gd32h77x_entropy_diagnostics_t diagnostics = {0};
            char panic_message[192];
            const char *failure_class = "source-error";
            gd32h77x_entropy_get_diagnostics(&diagnostics);
            if (status == OPRT_RESOURCE_NOT_READY) {
                failure_class = "busy";
            } else if (status == OPRT_TIMEOUT) {
                failure_class = "no-ready";
            } else if (diagnostics.stage == GD32H77X_ENTROPY_STAGE_CONTINUOUS_TEST) {
                failure_class = "repeated-sample";
            } else if (diagnostics.trng_stat != 0U) {
                failure_class = "trng-status";
            }
            (void)snprintf(panic_message, sizeof(panic_message),
                           "TRNG failure class=%s err=%ld stage=%lu STAT=%08lX CTL=%08lX HTCFG=%08lX ADDCTL0=%08lX RCU_CTL=%08lX clk=%lu regs=%lu ready=%08lX",
                           failure_class, (long)status, (unsigned long)diagnostics.stage,
                           (unsigned long)diagnostics.trng_stat, (unsigned long)diagnostics.trng_ctl,
                           (unsigned long)diagnostics.trng_htcfg, (unsigned long)diagnostics.rcu_addctl0,
                           (unsigned long)diagnostics.rcu_ctl, (unsigned long)diagnostics.trng_clock_enabled,
                           (unsigned long)diagnostics.trng_registers_valid,
                           (unsigned long)diagnostics.last_ready_stat);
            gd32h77x_platform_panic(panic_message);
            return -1;
        }
    } while (sample < threshold);
    return gd32h77x_random_as_int(sample % bound);
    // --- END: user implements ---
}

/**
 * @brief Get system reset reason
 *
 * @param[in] describe: point to reset reason describe
 *
 * @return reset reason
 */
TUYA_RESET_REASON_E tkl_system_get_reset_reason(char **describe)
{
    // --- BEGIN: user implements ---

    uint32_t            flags  = gd32h77x_platform_reset_flags();
    TUYA_RESET_REASON_E reason = TUYA_RESET_REASON_UNKNOWN;
    const char         *text   = "unknown";
    if (flags & (RCU_RSTSCK_FWDGTRSTF | RCU_RSTSCK_WWDGTRSTF)) {
        reason = TUYA_RESET_REASON_HW_WDOG;
        text   = "watchdog";
    } else if (flags & RCU_RSTSCK_SWRSTF) {
        reason = TUYA_RESET_REASON_SOFTWARE;
        text   = "software";
    } else if (flags & RCU_RSTSCK_PORRSTF) {
        reason = TUYA_RESET_REASON_POWERON;
        text   = "power on";
    } else if (flags & RCU_RSTSCK_BORRSTF) {
        reason = TUYA_RESET_REASON_BROWNOUT;
        text   = "brownout";
    } else if (flags & RCU_RSTSCK_EPRSTF) {
        reason = TUYA_RESET_REASON_EXTERNAL;
        text   = "external";
    }
    if (describe) {
        *describe = (char *)text;
    }
    return reason;
    // --- END: user implements ---
}

