void tkl_system_sleep(uint32_t num_ms)
{
    // --- BEGIN: user implements ---

    if (num_ms) {
        vTaskDelay(gd32h77x_timeout_ticks(num_ms));
    } else {
        taskYIELD();
    }
    // --- END: user implements ---
}

/**
 * @brief system delay
 *
 * @param[in] msTime: time in MS
 *
 * @note This API is used for system sleep.
 *
 * @return void
 */
void tkl_system_delay(uint32_t num_ms)
{
    // --- BEGIN: user implements ---

    /* Board initialization enables the Cortex-M7 cycle counter. */
    for (uint32_t i = 0; i < num_ms; ++i) {
        uint32_t start = DWT->CYCCNT;
        while ((uint32_t)(DWT->CYCCNT - start) < SystemCoreClock / 1000U) {
            __NOP();
        }
    }
    // --- END: user implements ---
}

